import {REGIONS,RATES,isShiny} from './model.mjs';
import {profile,level} from './training.mjs';
import * as Art from './art.mjs';
const SIZE=36,fold=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export class PokemonLibrary{
 constructor(g){this.g=g;this.filters={}}
 settings(context){return this.filters[context]||= {query:'',gen:'',rarity:'',owned:'owned',shiny:'',type:'',sort:'id',page:0}}
 render(context,action,selected=[]){const g=this.g,f=this.settings(context),owned=new Set(g.state.roster);let keys=f.owned==='owned'?[...owned]:Object.values(g.dex).flatMap(d=>[String(d.id),...(d.shiny?[d.id+'s']:[])]);keys=keys.filter(k=>{const d=g.poke(k);return(f.owned!=='missing'||!owned.has(k))&&(!f.gen||d.gen===+f.gen)&&(!f.rarity||d.rarity===f.rarity)&&(!f.type||d.types.includes(f.type))&&(!f.shiny||(f.shiny==='yes')===isShiny(k))&&(!f.query||fold(d.name+' '+d.id).includes(fold(f.query)))});const value=k=>f.sort==='name'?g.poke(k).name:f.sort==='level'?-(owned.has(k)?level(profile(g.state,k)):0):f.sort==='iv'?-(owned.has(k)?profile(g.state,k).iv.reduce((a,b)=>a+b,0):0):parseInt(k);keys.sort((a,b)=>typeof value(a)==='string'?value(a).localeCompare(value(b),'fr'):value(a)-value(b)||Number(isShiny(a))-Number(isShiny(b)));const pages=Math.max(1,Math.ceil(keys.length/SIZE));f.page=Math.min(f.page,pages-1);
 const select=(key,label,options)=>`<label>${label}<select data-library-filter="${key}" data-context="${context}">${options.map(([v,n])=>`<option value="${v}" ${String(f[key])===String(v)?'selected':''}>${n}</option>`).join('')}</select></label>`;
 return `<section class="library" data-library="${context}"><div class="library-filters"><label class="library-search">Recherche<input data-library-filter="query" data-context="${context}" value="${g.escape(f.query)}" placeholder="Nom ou numéro…" aria-label="Rechercher un Pokémon"></label>${select('gen','Génération',[['','Toutes'],...REGIONS.map((r,i)=>[i+1,`${i+1} · ${r}`])])}${select('rarity','Rareté',[['','Toutes'],...RATES.map(r=>[r.key,r.name])])}${select('owned','Collection',[['owned','Obtenus'],['all','Tous'],['missing','Non obtenus']])}${select('shiny','Chromatique',[['','Toutes les variantes'],['no','Normal'],['yes','Chromatique ✧']])}${select('type','Type',[['','Tous'],...Object.entries(Art.TYPE_NAMES)])}${select('sort','Trier par',[['id','Numéro'],['name','Nom'],['level','Niveau'],['iv','Meilleurs IV']])}</div><div class="library-count"><b>${keys.length} résultat${keys.length>1?'s':''}</b><span>Page ${f.page+1} / ${pages}</span><button data-act="library-reset" data-context="${context}">Réinitialiser</button></div><div class="mon-grid">${keys.slice(f.page*SIZE,(f.page+1)*SIZE).map(k=>{const d=g.poke(k),has=owned.has(k),p=has?profile(g.state,k):null;return `<button class="mon-card ${selected.includes(k)?'selected':''} ${isShiny(k)?'shiny-card':''} ${!has?'not-owned':''}" data-act="${action}" data-key="${k}" ${!has?'disabled':''}><small>#${String(d.id).padStart(3,'0')} ${isShiny(k)?'✧ CHROMATIQUE':''}</small><canvas width="130" height="105" data-mon="${k}"></canvas><b>${d.name}</b><span class="rarity-tag ${d.rarity}">${g.rarity(d.rarity).name}</span><span>${has?'Niv. '+level(p)+' · IV '+p.iv.reduce((a,b)=>a+b,0)+'/186':'Non obtenu'}</span>${(g.state.shinyCopies?.[k]||0)>1?`<small>×${g.state.shinyCopies[k]} exemplaires conservés</small>`:''}${selected.includes(k)?'<i>✓ Sélectionné</i>':''}</button>`}).join('')||'<div class="panel empty-state">Aucun Pokémon ne correspond à ces critères.</div>'}</div><div class="library-pagination"><button data-act="library-page" data-context="${context}" data-page="${f.page-1}" ${!f.page?'disabled':''}>← Précédent</button><span>${f.page+1} / ${pages}</span><button data-act="library-page" data-context="${context}" data-page="${f.page+1}" ${f.page>=pages-1?'disabled':''}>Suivant →</button></div></section>`}
 change(input){const context=input.dataset.context,f=this.settings(context),name=input.dataset.libraryFilter;f[name]=input.value;f.page=0;const pos=input.selectionStart;this.g.render();const next=this.g.root.querySelector(`[data-library-filter="${name}"][data-context="${context}"]`);next?.focus();if(name==='query')next?.setSelectionRange(pos,pos)}
 action(act,d){if(act==='library-reset'){delete this.filters[d.context]}else this.settings(d.context).page=Math.max(0,+d.page||0);this.g.render()}
}
